// Runnable demo. FakeRedis stands in for a real Redis server.
// Each class would be its own file in a real project.
package com.bank.interest;

import java.math.BigDecimal;
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class InterestLockDemo {
    private static final Logger log = Logger.getLogger(InterestLockDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        FakeRedis redis = new FakeRedis();
        AccountRepository repo = new AccountRepository();
        repo.save(new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000.00")));
        repo.save(new Account("CUR3001", "Priya Sharma", new BigDecimal("250000.00")));

        // Three "instances" race to run the nightly interest posting at 2 AM.
        ExecutorService pool = Executors.newFixedThreadPool(3);
        CountDownLatch start = new CountDownLatch(1);
        for (int i = 1; i <= 3; i++) {
            final String instanceId = "instance-" + i;
            pool.submit(() -> {
                try { start.await(); } catch (InterruptedException ignored) { }
                RedisDistributedLock lock = new RedisDistributedLock(redis, "lock:interest-posting", 120);
                InterestPostingJob job = new InterestPostingJob(lock, repo, instanceId);
                job.runNightly();
            });
        }
        start.countDown();   // release all three at once — simulate simultaneous cron fire
        pool.shutdown();
        pool.awaitTermination(5, TimeUnit.SECONDS);

        log.info(() -> "FINAL Rajesh balance = " + repo.find("SAV2001").balance);
        log.info(() -> "FINAL Priya balance  = " + repo.find("CUR3001").balance);
    }
}

// ─── model/Account.java ───
class Account {
    final String accountId, holderName; BigDecimal balance;
    Account(String accountId, String holderName, BigDecimal balance) {
        this.accountId = accountId; this.holderName = holderName; this.balance = balance;
    }
    void credit(BigDecimal amt) { balance = balance.add(amt); }
}

// ─── repository/AccountRepository.java ───
class AccountRepository {
    private final Map<String, Account> db = new ConcurrentHashMap<>();
    void save(Account a) { db.put(a.accountId, a); }
    Account find(String id) { return db.get(id); }
    Collection<Account> all() { return db.values(); }
}

// ─── lock/DistributedLock.java ───
interface DistributedLock {
    String tryAcquire();              // returns token if acquired, null if not
    boolean release(String token);    // true if this owner released
}

// ─── lock/RedisDistributedLock.java ───
// Core logic: SET NX PX (setIfAbsent + TTL) to acquire, token-checked
// atomic Lua DEL to release.
class RedisDistributedLock implements DistributedLock {
    private final FakeRedis redis; private final String key; private final long ttlSeconds;
    RedisDistributedLock(FakeRedis redis, String key, long ttlSeconds) {
        this.redis = redis; this.key = key; this.ttlSeconds = ttlSeconds;
    }
    public String tryAcquire() {
        String token = UUID.randomUUID().toString();       // unique per acquisition
        boolean ok = redis.setIfAbsent(key, token, ttlSeconds * 1000); // SET key token NX PX ttl
        return ok ? token : null;
    }
    public boolean release(String token) {
        // Atomic: delete only if the stored value is still MY token.
        // Real Redis: EVAL "if get(KEYS[1])==ARGV[1] then return del(KEYS[1]) else return 0 end"
        return redis.compareAndDelete(key, token);
    }
}

// ─── job/InterestPostingJob.java ───
// Scheduled nightly job, guarded by the distributed lock. Idempotent as a safety net.
class InterestPostingJob {
    private static final Logger log = Logger.getLogger(InterestPostingJob.class.getName());
    private static final BigDecimal DAILY_RATE = new BigDecimal("0.0001096"); // ~4%/365
    private final DistributedLock lock; private final AccountRepository repo; private final String instanceId;

    InterestPostingJob(DistributedLock lock, AccountRepository repo, String instanceId) {
        this.lock = lock; this.repo = repo; this.instanceId = instanceId;
    }

    void runNightly() {
        String token = lock.tryAcquire();
        if (token == null) {
            log.info(instanceId + " did NOT get the lock — skipping (another instance is posting)");
            return;
        }
        try {
            log.info(instanceId + " ACQUIRED lock — posting interest");
            for (Account a : repo.all()) {
                BigDecimal interest = a.balance.multiply(DAILY_RATE)
                        .setScale(2, java.math.RoundingMode.HALF_EVEN);
                a.credit(interest);
                log.info(() -> instanceId + " credited " + interest + " to " + a.accountId
                        + " (" + a.holderName + "), new balance " + a.balance);
            }
        } finally {
            boolean released = lock.release(token);         // only releases MY lock
            log.fine(instanceId + " released lock = " + released);
        }
    }
}

// ─── Simulated thread-safe Redis supporting SET NX PX and token-checked DEL ───
class FakeRedis {
    private static class Entry { final String value; final long expireAt;
        Entry(String v, long e) { value = v; expireAt = e; } }
    private final Map<String, Entry> store = new HashMap<>();

    synchronized boolean setIfAbsent(String key, String value, long ttlMs) {
        long now = System.currentTimeMillis();
        Entry e = store.get(key);
        if (e != null && e.expireAt > now) return false;    // held and not expired → NX fails
        store.put(key, new Entry(value, now + ttlMs));      // acquire with TTL
        return true;
    }
    synchronized boolean compareAndDelete(String key, String token) {
        Entry e = store.get(key);
        if (e != null && e.value.equals(token)) { store.remove(key); return true; }
        return false;                                       // not my token → do not delete
    }
}

